import{_ as a,o,c as s,a2 as r}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Présentation de Kodus","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),t={name:"guide/index.md"};function n(i,e,l,u,d,c){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="presentation-de-kodus" tabindex="-1">Présentation de Kodus <a class="header-anchor" href="#presentation-de-kodus" aria-label="Permalink to &quot;Présentation de Kodus&quot;">​</a></h1><p>Kodus est un launcher pour Minecraft Java Edition qui permet de jouer avec ou sans mods, sans compte Microsoft : un simple pseudo suffit.</p><p>Un <strong>launcher</strong> est le programme qui télécharge et lance Minecraft. Le launcher officiel lance le jeu de base. Un <strong>launcher moddé</strong> comme Kodus permet en outre d&#39;installer des <strong>mods</strong> (des ajouts au jeu : nouvelles créatures, meilleures performances, minicarte…), des packs de textures et des shaders, en quelques clics.</p><p>Kodus gère tout le reste : il télécharge Java, la version de Minecraft choisie et les composants nécessaires aux mods. Aucune installation supplémentaire n&#39;est requise.</p><h2 id="par-ou-commencer" tabindex="-1">Par où commencer <a class="header-anchor" href="#par-ou-commencer" aria-label="Permalink to &quot;Par où commencer&quot;">​</a></h2><ol><li><a href="./installer">Installer Kodus</a> sur Windows ou macOS.</li><li><a href="./premier-lancement">Premier lancement</a> : choix du pseudo et création de votre première instance.</li><li><a href="./lexique">Glossaire</a>, pour comprendre les termes « instance », « loader », etc.</li><li><a href="./mods">Ajouter des mods</a>, puis <a href="./jouer">jouer en multijoueur</a>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Besoin d&#39;aide ?</p><p>La page <a href="./depannage">Résolution des problèmes</a> couvre la plupart des situations. Pour le reste, contactez l&#39;équipe Kodus en joignant vos logs (bouton <strong>Copier</strong> de l&#39;onglet Logs).</p></div>',7)])])}const h=a(t,[["render",n]]);export{m as __pageData,h as default};
